<template>
  <section class="panel">
    <div class="panel-head"><div><h2>公司組</h2><p>香港／澳門公司、內地公司與所屬牌照。</p></div><div v-if="isAdmin" class="heading-actions"><button class="button" @click="dialog = 'new-group'; dialogForm = { name: '', notes: '' }">＋ 新增公司組</button><button class="button primary" @click="newCompany">＋ 新增公司</button></div></div>
    <div v-if="!groups.length" class="empty">尚未建立公司組</div>
    <div v-for="group in groups" :key="group.id" class="company-group-block">
      <div class="panel-head"><div><h3>{{ group.name }}</h3><p>{{ group.notes || '尚未填寫公司組備註' }}</p></div><button v-if="isAdmin" class="button" @click="dialog = 'group'; dialogForm = { ...group }">編輯公司組</button></div>
      <div v-if="group.warnings?.length" class="status-warnings"><span v-for="warning in group.warnings" :key="warning" class="warning">{{ warning }}</span></div>
      <div class="table-wrap"><table><thead><tr><th>香港／澳門公司</th><th>內地公司</th><th>牌照</th><th>狀態標籤</th></tr></thead><tbody><tr><td><div v-for="company in foreignCompanies(group)" :key="company.id"><CompanyName :company="company" /></div><span v-if="!foreignCompanies(group).length">未登記</span></td><td>{{ mainlandCompanies(group).map(item => item.name).join('、') || '未登記' }}</td><td>{{ group.plates.length }} 個牌照</td><td>{{ group.warnings?.join('、') || '正常' }}</td></tr></tbody></table></div>
      <div class="company-columns"><div><h3>香港／澳門公司</h3><div v-for="company in foreignCompanies(group)" :key="company.id" class="company-card" :class="companyCardClass(company)"><div class="company-card-title"><span>{{ company.jurisdiction }} · <CompanyName :company="company" /></span><span class="company-status" :class="statusClass(company.status)">{{ company.status }}</span></div><span>{{ company.jurisdiction === '香港' ? '商業登記號碼（BR）' : '商業登記編號' }}：{{ company.registration_no || '—' }}</span><span v-if="company.jurisdiction === '香港'">公司編號（CR）：{{ company.company_number || '—' }}</span><span>成立日期：{{ company.incorporated_on || '—' }}</span><template v-if="company.jurisdiction === '香港'"><label class="inline-date">{{ company.brExpiresOn ? `BR 到期：${company.brExpiresOn}` : 'BR 到期待錄入' }}<input v-model="brDates[company.id]" type="date" aria-label="BR 到期日" /></label><button class="button" @click="saveBr(company)">儲存 BR 日期</button><span>下一次周年申報（NAR1）：{{ company.nar1DueOn || '成立日期待錄入' }}</span></template><button v-if="isAdmin" class="button" @click="editCompany(company)">編輯</button><ExpiryPanel owner-type="company" :owner-id="company.id" @saved="saved" @error="emit('error', $event)" /><ServiceScope v-if="isAdmin" owner-type="company" :owner-id="company.id" :is-self="isSelf" @saved="saved" @error="emit('error', $event)" /><div v-if="company.jurisdiction === '香港'" class="record-row"><span>註冊地址／秘書合約到期：{{ contractDates[company.id] || '待錄入' }}</span><DateInput v-model="contractDates[company.id]" :label="`${company.name}合約到期`" /><button class="text-button" @click="saveContract(company)">儲存日期</button></div></div></div>
      <div><h3>內地公司</h3><div v-for="company in mainlandCompanies(group)" :key="company.id" class="company-card" :class="companyCardClass(company)"><div class="company-card-title"><strong>內地 · {{ company.name }}</strong><span class="company-status" :class="statusClass(company.status)">{{ company.status }}</span></div><span>統一社會信用代碼：{{ company.registration_no || '—' }}</span><span>成立日期：{{ company.incorporated_on || '—' }}</span><span>納稅人類型：{{ company.taxpayer_type || '—' }}</span><button v-if="isAdmin" class="button" @click="editCompany(company)">編輯</button><ExpiryPanel owner-type="company" :owner-id="company.id" @saved="saved" @error="emit('error', $event)" /><ServiceScope v-if="isAdmin" owner-type="company" :owner-id="company.id" :is-self="isSelf" @saved="saved" @error="emit('error', $event)" /><div class="record-row"><span>註冊地址合約到期：{{ contractDates[company.id] || '待錄入' }}</span><DateInput v-model="contractDates[company.id]" :label="`${company.name}合約到期`" /><button class="text-button" @click="saveContract(company)">儲存日期</button></div></div></div></div>
      <div class="group-plates"><h3>所屬兩地牌</h3><div v-for="plate in group.plates" :key="plate.id" class="record-row"><button class="phase-link" @click="emit('plate', plate.id)"><PlateChip :plate="plate.mainland_plate" /> · <PlateChip :plate="plate.local_plate" :route="plate.route" /></button><span>{{ plate.route }} · 口岸：{{ plate.port || '待設定' }}</span><span>{{ plate.usage_status }}</span></div><div v-if="!group.plates.length" class="empty">尚未掛接兩地牌</div></div>
    </div>
    <div v-if="ungrouped.length" class="company-group-block"><h3>未分組公司</h3><div class="company-columns"><div v-for="company in ungrouped" :key="company.id" class="company-card"><span>{{ company.jurisdiction }} · <CompanyName :company="company" /></span><span>{{ registrationLabel(company.jurisdiction) }}：{{ company.registration_no || '—' }}</span><span v-if="company.jurisdiction === '香港'">公司編號（CR）：{{ company.company_number || '—' }}</span><template v-if="company.jurisdiction === '香港'"><label class="inline-date">{{ company.brExpiresOn ? `BR 到期：${company.brExpiresOn}` : 'BR 到期待錄入' }}<input v-model="brDates[company.id]" type="date" aria-label="BR 到期日" /></label><button class="button" @click="saveBr(company)">儲存 BR 日期</button><span>下一次周年申報（NAR1）：{{ company.nar1DueOn || '成立日期待錄入' }}</span></template><span v-if="company.jurisdiction === '內地'">納稅人類型：{{ company.taxpayer_type || '—' }}</span><span>狀態：{{ company.status }}</span><button v-if="isAdmin" class="button" @click="editCompany(company)">編輯</button><ExpiryPanel owner-type="company" :owner-id="company.id" @saved="saved" @error="emit('error', $event)" /><ServiceScope v-if="isAdmin" owner-type="company" :owner-id="company.id" :is-self="isSelf" @saved="saved" @error="emit('error', $event)" /><div v-if="['香港', '內地'].includes(company.jurisdiction)" class="record-row"><span>{{ company.jurisdiction === '香港' ? '註冊地址／秘書合約到期' : '註冊地址合約到期' }}：{{ contractDates[company.id] || '待錄入' }}</span><DateInput v-model="contractDates[company.id]" :label="`${company.name}合約到期`" /><button class="text-button" @click="saveContract(company)">儲存日期</button></div></div></div></div>
  </section>
  <FormDialog :open="!!dialog" :title="dialog === 'new-group' ? '新增公司組' : dialog === 'group' ? '編輯公司組' : dialog === 'new-company' ? '新增公司' : '編輯公司'" :submit-text="dialog === 'group' || dialog === 'new-group' ? '儲存公司組' : '儲存公司'" @close="dialog = null" @submit="submit">
    <template v-if="dialog === 'group' || dialog === 'new-group'"><Field label="公司組名稱" required><TextInput v-model="dialogForm.name" /></Field><Field label="備註"><TextInput v-model="dialogForm.notes" /></Field></template>
    <template v-else><div class="form-grid">
      <Field label="公司組"><Select v-model="dialogForm.groupId" :options="groupOptions" /></Field>
      <Field label="司法區"><Select v-model="dialogForm.jurisdiction" :options="['香港', '澳門', '內地']" /></Field>
      <div class="company-name-fields"><Field label="公司名稱" required><TextInput v-model="dialogForm.name" /></Field><div v-if="nameSuggestion && dialogForm.jurisdiction === '內地'" class="company-suggestion"><p class="error">{{ nameProblem }}</p><Button variant="text" size="sm" @click="dialogForm.name = nameSuggestion; nameSuggestion = ''; nameProblem = ''">改用建議名稱</Button></div><Field v-if="dialogForm.jurisdiction === '香港'" label="英文名稱" required><TextInput v-model="dialogForm.nameEn" /></Field></div>
      <Field :label="registrationLabel(dialogForm.jurisdiction)"><TextInput v-model="dialogForm.registrationNo" /></Field>
      <Field v-if="dialogForm.jurisdiction === '香港'" label="公司編號（CR）"><TextInput v-model="dialogForm.companyNumber" /></Field>
      <Field label="成立日期"><DateInput v-model="dialogForm.incorporatedOn" label="成立日期" /></Field>
      <Field v-if="dialogForm.jurisdiction === '內地'" label="納稅人類型"><Select v-model="dialogForm.taxpayerType" :options="[{ value: '', label: '待選擇' }, { value: '小規模納稅人', label: '小規模納稅人' }, { value: '一般納稅人', label: '一般納稅人' }]" /></Field>
      <Field label="狀態"><Select v-model="dialogForm.status" :options="statuses" /></Field>
      <Field label="狀態變更日期"><DateInput v-model="dialogForm.statusChangedOn" label="狀態變更日期" /></Field>
      <Field label="備註"><TextInput v-model="dialogForm.notes" /></Field>
    </div><div v-if="dialogForm.jurisdiction === '香港' && dialog === 'company'" class="lookup-box"><button type="button" class="button" :disabled="lookingUp" @click="lookupCompany">{{ lookingUp ? '查詢中…' : '向公司註冊處查詢' }}</button><p v-if="lookupError" class="error">{{ lookupError }}</p><div v-if="lookupResult" class="lookup-result"><strong>{{ lookupResult.name }}</strong><span>BRN：{{ lookupResult.registrationNo }}</span><span>英文名稱：{{ lookupResult.englishName || '—' }}</span><span>成立日期：{{ lookupResult.incorporatedOn || '—' }}</span><span>公司類型：{{ lookupResult.companyType || '—' }}</span><span>註冊地址：{{ lookupResult.address || '—' }}</span><button type="button" class="button primary" @click="applyLookup">套用查詢結果</button></div></div></template>
  </FormDialog>
</template>
<script setup>
import { ref, computed, watch } from 'vue'
import { api, user } from '../api'
import ExpiryPanel from '../components/ExpiryPanel.vue'
import ServiceScope from '../components/ui/ServiceScope.vue'
import FormDialog from '../components/business/FormDialog.vue'
import CompanyName from '../components/business/CompanyName.vue'
import Button from '../components/ui/Button.vue'
import PlateChip from '../components/ui/PlateChip.vue'
import Field from '../components/ui/Field.vue'
import TextInput from '../components/ui/TextInput.vue'
import Select from '../components/ui/Select.vue'
import DateInput from '../components/ui/DateInput.vue'
const props = defineProps({ initialCustomer: String, addGroupRequest: Number, isSelf: Boolean })
const emit = defineEmits(['error', 'saved', 'plate'])
const isAdmin = user()?.role === 'admin'
const statuses = ['存續', '經營異常', '註銷中', '已註銷']
const groups = ref([]), companies = ref([]), dialog = ref(null), dialogForm = ref({}), brDates = ref({}), contractDates = ref({}), lookingUp = ref(false), lookupResult = ref(null), lookupError = ref(''), nameSuggestion = ref(''), nameProblem = ref('')
const ungrouped = computed(() => companies.value.filter(item => !item.group_id))
const groupOptions = computed(() => [{ value: '', label: '未分組' }, ...groups.value.map(group => ({ value: group.id, label: group.name }))])
const foreignCompanies = group => group.companies.filter(item => item.jurisdiction !== '內地')
const mainlandCompanies = group => group.companies.filter(item => item.jurisdiction === '內地')
const statusClass = status => ({ '經營異常': 'warning', '註銷中': 'warning', '已註銷': 'dissolved' }[status] || '')
const companyCardClass = company => company.status === '已註銷' ? 'company-dissolved' : ''
const registrationLabel = jurisdiction => ({ 香港: '商業登記號碼（BR）', 澳門: '商業登記編號', 內地: '統一社會信用代碼' }[jurisdiction] || '登記號碼')
async function load() { if (!props.initialCustomer) return; try { [groups.value, companies.value] = await Promise.all([api(`/company-groups?customerId=${encodeURIComponent(props.initialCustomer)}`), api(`/companies?customerId=${encodeURIComponent(props.initialCustomer)}`)]); brDates.value = Object.fromEntries(companies.value.filter(item => item.jurisdiction === '香港').map(item => [item.id, item.brExpiresOn || ''])); const tracked = await Promise.all(companies.value.map(item => api(`/tracked-items?ownerType=company&ownerId=${item.id}`))); contractDates.value = Object.fromEntries(companies.value.map((company, index) => [company.id, tracked[index].find(item => item.code === contractCode(company))?.expiresOn || ''])) } catch (error) { emit('error', error) } }
const contractCode = company => company.jurisdiction === '香港' ? 'hk_registered_office' : 'cn_registered_address'
async function saveContract(company) { try { await api('/tracked-items', 'PUT', { ownerType: 'company', ownerId: company.id, code: contractCode(company), expiresOn: contractDates.value[company.id] || '' }); saved('合約日期已儲存') } catch (error) { emit('error', error) } }
function saved(message) { load(); emit('saved', message) }
function newCompany() { dialog.value = 'new-company'; dialogForm.value = { groupId: '', jurisdiction: '香港', name: '', registrationNo: '', companyNumber: '', incorporatedOn: '', taxpayerType: '', status: '存續', statusChangedOn: '', nameEn: '', notes: '' }; nameSuggestion.value = ''; nameProblem.value = '' }
function editCompany(company) { dialog.value = 'company'; dialogForm.value = { ...company, nameEn: company.nameEn || company.name_en || '', groupId: company.group_id || '', registrationNo: company.registration_no || '', companyNumber: company.company_number || '', incorporatedOn: company.incorporated_on || '', taxpayerType: company.taxpayer_type || '', statusChangedOn: company.status_changed_on || '' }; lookupResult.value = null; lookupError.value = ''; nameSuggestion.value = ''; nameProblem.value = '' }
async function saveGroup() { try { const isNew = dialog.value === 'new-group'; await api(isNew ? '/company-groups' : `/company-groups/${dialogForm.value.id}`, isNew ? 'POST' : 'PATCH', { ...dialogForm.value, customerId: props.initialCustomer }); dialog.value = null; saved('公司組已儲存') } catch (error) { emit('error', error) } }
async function saveCompany() { nameSuggestion.value = ''; nameProblem.value = ''; try { const isNew = dialog.value === 'new-company'; await api(isNew ? '/companies' : `/companies/${dialogForm.value.id}`, isNew ? 'POST' : 'PATCH', { ...dialogForm.value, customerId: props.initialCustomer }); dialog.value = null; saved('公司已儲存') } catch (error) { if (error.details?.suggestion) { nameSuggestion.value = error.details.suggestion; nameProblem.value = error.message } else emit('error', error) } }
async function saveBr(company) { try { await api('/tracked-items', 'PUT', { ownerType: 'company', ownerId: company.id, code: 'hk_br', expiresOn: brDates.value[company.id] || '' }); saved('BR 日期已儲存') } catch (error) { emit('error', error) } }
async function lookupCompany() { lookupResult.value = null; lookupError.value = ''; if (!/^\d{8}$/.test(String(dialogForm.value.registrationNo || ''))) { lookupError.value = '請先填寫 8 位商業登記號碼'; return } lookingUp.value = true; try { lookupResult.value = await api(`/companies/${dialogForm.value.id}/hk-lookup`, 'POST') } catch (error) { lookupError.value = error.message } finally { lookingUp.value = false } }
function applyLookup() { if (!lookupResult.value) return; dialogForm.value.name = lookupResult.value.name || dialogForm.value.name; dialogForm.value.nameEn = lookupResult.value.englishName || dialogForm.value.nameEn; dialogForm.value.incorporatedOn = lookupResult.value.incorporatedOn || dialogForm.value.incorporatedOn }
function submit() { if (dialog.value === 'group' || dialog.value === 'new-group') saveGroup(); else saveCompany() }
watch(() => props.initialCustomer, load, { immediate: true })
watch(() => props.addGroupRequest, () => { dialog.value = 'new-group'; dialogForm.value = { name: '', notes: '' } }, { immediate: props.addGroupRequest > 0 })
</script>
